function audioTime(t){if(!Number.isFinite(t))return '0:00';return `${Math.floor(t/60)}:${String(Math.floor(t%60)).padStart(2,'0')}`}
function updateAudioUI(){const duration=Number.isFinite(audio.duration)?audio.duration:0,time=audio.currentTime||0,miniProgress=document.getElementById('global-audio-progress'),miniTime=document.getElementById('global-audio-time');if(miniProgress)miniProgress.style.width=(duration?Math.min(100,time/duration*100):0)+'%';if(miniTime)miniTime.textContent=duration?`${audioTime(time)} · ${audioTime(duration)}`:'Playing';const seek=document.getElementById('audio-seek');if(!seek||audioPlace!==ui.placeId&&ui.route==='story')return;const visible=ui.route==='arrival'?trip()?.plan.stops[trip()?.progress.index]?.id:ui.placeId;if(audioPlace!==visible)return;seek.max=duration||1;seek.value=time;seek.disabled=!duration;document.getElementById('audio-time').textContent=audioTime(time);document.getElementById('audio-duration').textContent=duration?audioTime(duration):'Load to see length'}
audio.addEventListener('timeupdate',()=>{rememberAudio();updateAudioUI()});audio.addEventListener('loadedmetadata',()=>{restoreAudio();updateAudioUI()});audio.addEventListener('play',()=>{audioPlaying=true;audioLoading=false;ui.keepScroll=true;render()});audio.addEventListener('pause',()=>{rememberAudio();persist();audioPlaying=false;ui.keepScroll=true;render()});audio.addEventListener('ended',()=>{if(audioPlace)db.audioPositions[audioPlace]=0;persist();audioPlaying=false;render()});audio.addEventListener('error',()=>{audioLoading=false;audioError='This audio file could not load. Read the transcript or download this tour while connected.';ui.keepScroll=true;render()});
async function play(id){const p=P[id];if(!p.story.audio){audioError='No recording is bundled for this stop. Read the available text.';audioPlace=id;render();return}if(audioPlace===id&&!audio.paused){audio.pause();return}if(offline()){const has=Object.values(db.packages).some(pk=>pk.assets.includes(p.story.audio));if(!has){audioPlace=id;audioError='This story has not been downloaded. Reconnect to load it, or read the saved transcript.';render();return}try{const cache=await caches.open(CACHE);if(!(await cache.match(new URL(p.story.audio,location.href).href))){audioPlace=id;audioError='The browser has removed this cached file. Reconnect and refresh the package.';render();return}}catch(e){audioPlace=id;audioError='Offline cache is unavailable in this browser.';render();return}}
if(audioPlace!==id){audio.pause();audioPlace=id;audio.src=p.story.audio;audio.currentTime=0}audioError='';audioLoading=true;render();try{await audio.play()}catch(e){audioLoading=false;audioError='Playback could not start. Tap Play again or read the transcript.';render()}}
function saveTrip(plan){const id='trip-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),t={id,plan:{...copy(plan),id,revision:plan.revision||0},status:'upcoming',progress:{index:0,phase:'leg',visited:[],skipped:[]},createdAt:new Date().toISOString()};db.trips.unshift(t);persist();ui.tripId=id;ui.proposal=null;ui.history=[{route:'home',placeId:ui.placeId,tripId:null,stopTab:'listen'}];go('ready',true);toast('Tour saved in this browser')}
function beginTrip(confirmed=false){const t=trip();if(!t||!['upcoming','paused','active'].includes(t.status)){toast('Open a saved or paused trip to start.');return}const issues=C.validate(t.plan);if(issues.length){toast(issues.join(' '));return}const other=db.trips.some(x=>x.status==='active'&&x.id!==t.id);if(other&&confirmed!==true){showModal('switch');return}db.trips.filter(x=>x.status==='active'&&x.id!==t.id).forEach(x=>x.status='paused');t.status='active';persist();go(t.progress.phase==='stop'?'arrival':'leg')}
function returnTrip(reset=false){const t=trip();if(!t){go('trips');return}go(t.status==='upcoming'?'ready':t.status==='paused'?'paused':t.status==='active'?(t.progress.phase==='stop'?'arrival':'leg'):'completed',reset===true)}
function advance(skip=false){const t=trip(),stop=t?.plan.stops[t?.progress.index];if(!t||t.status!=='active'||!stop){toast('There is no active stop to advance.');return}const id=stop.id;if(!skip&&(t.progress.phase!=='stop'||!t.progress.visited.includes(id))){toast('Confirm that you have arrived before finishing this stop.');return}if(skip&&t.progress.visited.includes(id)){toast('This visit is already confirmed. Finish the stop instead of marking it skipped.');return}if(skip&&!t.progress.skipped.includes(id))t.progress.skipped.push(id);audio.pause();if(t.progress.index===t.plan.stops.length-1){t.status='completed';t.completedAt=new Date().toISOString();persist();go('completed')}else{t.progress.index++;t.progress.phase='leg';ui.navStep=0;persist();go('leg')}}
function startEdit(source='trip',plan=null){const t=source==='trip'||source==='pending'?trip():null;if(!t&&!ui.proposal?.plan){toast('Open a plan before editing.');return}if(t&&!['upcoming','active','paused'].includes(t.status)){toast('This journey is complete. Make a new copy to edit it.');return}if(source==='pending'&&(!ui.pendingBase||ui.pendingBase.tripId!==t.id||ui.pendingBase.planStamp!==planStamp(t.plan)||ui.pendingBase.progressStamp!==progressStamp(t))){toast('The tour changed. Review the current visit before extending it.');return}ui.edit={source,tripId:t?.id,basePlan:copy(t?.plan||ui.proposal.plan),plan:copy(plan||t?.plan||ui.proposal.plan),basePlanStamp:planStamp(t?.plan||ui.proposal.plan),baseProgressStamp:t?progressStamp(t):null,currentExtension:source==='pending'?copy(ui.pendingBase.currentExtension):null,unlockedIds:[],undo:null};go('edit')}
function commitPlan(plan,context,guard={}){const t=context==='proposal'?null:db.trips.find(t=>t.id===(context||ui.tripId)),current=context==='proposal'?ui.proposal?.plan:t?.plan;if(!current){toast('This plan is no longer available.');return false}if(t&&!['upcoming','active','paused'].includes(t.status)){toast('A completed journey stays unchanged. Create a new copy instead.');return false}if(guard.basePlanStamp&&guard.basePlanStamp!==planStamp(current)||t&&guard.baseProgressStamp&&guard.baseProgressStamp!==progressStamp(t)){ui.error='This preview is stale because the saved tour or progress changed. Keep the current tour and reopen the change.';toast(ui.error);return false}const issues=C.validate(plan);if(issues.length){toast(issues.join(' '));return false}if(t){const replacement=guard.replacement,allowed=new Set(guard.allowUnlockIds||[]),fixed=preserved(t);for(let i=0;i<fixed.length;i++){const old=t.plan.stops[i],next=plan.stops[i],replaceCurrent=replacement&&i===replacement.index&&old.id===replacement.targetId&&i===t.progress.index&&!t.progress.visited.includes(old.id)&&!t.progress.skipped.includes(old.id),extendCurrent=currentExtensionAllowed(t,plan,guard,i);if(!replaceCurrent&&!extendCurrent&&(!next||next.id!==old.id||next.duration!==old.duration||!!next.locked!==!!old.locked)){toast('Current and previously visited stops must stay unchanged.');return false}}for(const old of t.plan.stops.filter(x=>x.locked)){const next=plan.stops.find(x=>x.id===old.id),index=t.plan.stops.indexOf(old);if(!allowed.has(old.id)&&!currentExtensionAllowed(t,plan,guard,index)&&(!next||next.duration!==old.duration||!next.locked)){toast('Unlock a must-visit explicitly before changing or removing it.');return false}}if(replacement){if(t.progress.index!==replacement.index||t.plan.stops[replacement.index]?.id!==replacement.targetId||t.progress.visited.includes(replacement.targetId)||t.progress.skipped.includes(replacement.targetId)){toast('That unavailable stop is no longer eligible for replacement.');return false}}}if(planSignature(plan)===planSignature(current)){toast('No changes to apply. Your saved tour is unchanged.');return false}const accepted=copy(plan);accepted.revision=(current.revision||0)+1;if(context==='proposal'){ui.proposal.plan=accepted}else{t.plan=accepted;if(guard.replacement){t.progress.index=Math.min(guard.replacement.index,accepted.stops.length-1);t.progress.phase='leg';ui.closedId=null}persist();ui.tripId=t.id}ui.review=null;ui.pending=null;ui.pendingBase=null;ui.edit=null;ui.replacement=null;ui.history=[{route:'home',placeId:ui.placeId,tripId:null,stopTab:'listen'}];if(context==='proposal')go('proposal',true);else returnTrip(true);toast('Changes applied');return true}
function newReview(before,plan,kind,context,request=''){const changes=planChanges(before,plan);if(!changes.length){toast('No changes to review. Your saved tour is unchanged.');return false}const t=context==='proposal'?null:db.trips.find(t=>t.id===(context||ui.tripId)),source=kind==='manual'?ui.edit:kind==='ai'?ui.adjustContext:null;ui.review={before:copy(before),plan:copy(plan),kind,context,request,changes,basePlanStamp:source?.basePlanStamp||planStamp(before),baseProgressStamp:source?.baseProgressStamp||(t?progressStamp(t):null),currentExtension:source?.currentExtension?copy(source.currentExtension):null,allowCurrentExtension:!!source?.currentExtension,allowUnlockIds:source?.unlockedIds?.slice()||[]};go('review');return true}
function openAdjust(source,plan=null){const t=source==='trip'||source==='pending'?trip():null;if(!t&&!ui.proposal?.plan){toast('Open a plan before requesting a change.');return}if(t&&!['upcoming','active','paused'].includes(t.status)){toast('This journey is complete. Make a new copy to adjust it.');return}if(source==='pending'&&(!ui.pendingBase||ui.pendingBase.tripId!==t.id||ui.pendingBase.planStamp!==planStamp(t.plan)||ui.pendingBase.progressStamp!==progressStamp(t))){toast('The tour changed. Reopen the current visit before adjusting it.');return}ui.adjustContext={source,tripId:t?.id,plan:copy(plan||t?.plan||ui.proposal.plan),basePlanStamp:planStamp(t?.plan||ui.proposal.plan),baseProgressStamp:t?progressStamp(t):null,currentExtension:source==='pending'?copy(ui.pendingBase.currentExtension):null};ui.adjustText='More beach time';ui.adjustLocks=ui.adjustContext.plan.stops.filter(s=>s.locked).map(s=>s.id);go('adjust')}

// Review/action boundaries: route navigation never implies consent to mutation.
function currentExtensionAllowed(t,plan,guard,index){const x=guard.allowCurrentExtension&&guard.currentExtension,old=t.plan.stops[index],next=plan.stops[index];return !!x&&index===t.progress.index&&index===x.index&&t.status==='active'&&t.progress.phase==='stop'&&t.progress.visited.includes(x.id)&&!t.progress.skipped.includes(x.id)&&old?.id===x.id&&next?.id===x.id&&old.duration===x.baseDuration&&x.duration===x.baseDuration+15&&next.duration===x.duration&&!!next.locked===!!old.locked}
function planSignature(p){return JSON.stringify({id:p?.id,title:p?.title,startId:p?.startId,startMinutes:p?.startMinutes,budget:p?.budget,mode:p?.mode,endMode:p?.endMode,date:p?.date,stops:(p?.stops||[]).map(x=>({id:x.id,duration:x.duration,locked:!!x.locked}))})}
function planStamp(p){return JSON.stringify([p?.revision||0,planSignature(p)])}
function progressStamp(t){return JSON.stringify({status:t.status,index:t.progress.index,phase:t.progress.phase,visited:t.progress.visited,skipped:t.progress.skipped})}
function planChanges(before,after){const changes=C.diff(before,after);for(const x of after.stops){const old=before.stops.find(y=>y.id===x.id);if(old&&!!old.locked!==!!x.locked)changes.push((x.locked?'Lock ':'Unlock ')+P[x.id].name)}return changes}
function draftDirty(){return !!ui.edit&&planSignature(ui.edit.plan)!==planSignature(ui.edit.basePlan)}
function editStopMutable(id){const e=ui.edit,t=e?.tripId&&db.trips.find(x=>x.id===e.tripId),stop=e?.plan.stops.find(x=>x.id===id);return !!stop&&!preserved(t).includes(id)&&!stop.locked}
function discardEdit(){const e=ui.edit;if(!e)return;ui.edit=null;ui.review=null;ui.modal=null;ui.pending=null;ui.pendingBase=null;ui.history=ui.history.filter(x=>!['edit','add-stop','review'].includes(x.route));if(e.source==='proposal')go('proposal');else{ui.tripId=e.tripId;returnTrip()}toast('Draft discarded; saved tour unchanged')}
function startReplacement(allowUnlock=false){const t=trip(),index=t?.progress.index,stop=t?.plan.stops[index];if(!t||!['active','paused'].includes(t.status)||!stop){toast('Open the current trip stop first.');return}if(t.progress.visited.includes(stop.id)||t.progress.skipped.includes(stop.id)){toast('This stop is already confirmed. Edit an upcoming stop instead.');startEdit('trip');return}if(stop.locked&&!allowUnlock){showModal('replaceLocked');return}ui.replacement={tripId:t.id,index,targetId:stop.id,basePlan:copy(t.plan),basePlanStamp:planStamp(t.plan),baseProgressStamp:progressStamp(t),allowUnlock};go('replacement')}
function replacementView(){const r=ui.replacement,t=r&&db.trips.find(x=>x.id===r.tripId);if(!r||!t)return planView();const options=Object.values(P).filter(p=>!p.isBreak&&!r.basePlan.stops.some(s=>s.id===p.id));return {title:'Replace unavailable stop',body:`<div class="page">${pageHero('Choose a different stop.','Only this unvisited current stop will be replaced. Review the new route and timing before applying.')}${notice('Closure and routes are demo scenarios. Candidate opening hours and access remain unverified.','warning')}<div class="card"><p class="eyebrow">Replacing</p><h2>${esc(P[r.targetId].name)}</h2></div>${options.map(p=>{const next=copy(r.basePlan);next.stops[r.index]={id:p.id,duration:p.duration,locked:false};const errors=C.validate(next).filter(x=>!x.startsWith('The plan exceeds')),s=timing(next);return `<div class="card">${placeRow(p.id,'place',C.formatDuration(p.duration)+' suggested')}<p class="small muted">New total ${C.formatDuration(s.totalMinutes)} · ${s.overBudget?C.formatDuration(s.overBudget)+' over budget':'within budget'}</p>${errors.length?notice(errors.join(' '),'warning'):btn('Preview this replacement','choose-replacement',{id:p.id},'secondary','refresh')}</div>`}).join('')||notice('No unused place is available. Keep this stop or skip it explicitly.')}</div>`,foot:footer(btn('Keep current stop','return-trip',{},'secondary'))}}
function previewReplacement(id){const r=ui.replacement,t=r&&db.trips.find(x=>x.id===r.tripId);if(!r||!t||!P[id]||P[id].isBreak||r.basePlan.stops.some(s=>s.id===id)){toast('Choose an unused catalogue place.');return}if(planStamp(t.plan)!==r.basePlanStamp||progressStamp(t)!==r.baseProgressStamp){toast('The trip changed. Reopen replacement for the current stop.');return}const next=copy(r.basePlan);next.stops[r.index]={id,duration:P[id].duration,locked:false};if(newReview(r.basePlan,next,'replacement',r.tripId,'Replace unavailable '+P[r.targetId].name+' with '+P[id].name)){ui.review.replacement={index:r.index,targetId:r.targetId};ui.review.baseProgressStamp=r.baseProgressStamp;ui.review.allowUnlockIds=r.allowUnlock?[r.targetId]:[]}}

async function generate(){ui.generationToken++;const token=ui.generationToken;ui.generation=0;go('generating');for(let i=0;i<3;i++){await new Promise(r=>setTimeout(r,430));if(token!==ui.generationToken||ui.route!=='generating')return;ui.generation=i;render()}if(offline()||ui.sim.generationFail){ui.sim.generationFail=false;ui.failure=offline()?'No connection in this scenario. Your inputs and saved tours are unchanged.':'The simulated request failed. No new tour was applied.';go('failure');return}const result=C.generate(req());if(result.ok){ui.tripId=null;ui.proposal=result;go('proposal')}else{ui.conflict=result;go('conflict')}}
function cancelGeneration(){ui.generationToken++;go('preferences');toast('Choices kept. No tour was saved.')}
function downloadsSupported(){return window.isSecureContext&&'caches'in window&&'serviceWorker'in navigator&&location.protocol!=='file:'}
async function download(){const t=trip();if(!t)return;if(ui.downloadBusy)return;if(!downloadsSupported()){ui.downloadError='Offline caching requires localhost or HTTPS. Start the included local server; your saved plan is safe.';render();return}if(offline()){ui.downloadError='Connect to save or update this package. Any existing downloaded version stays available.';render();return}ui.downloadBusy=true;ui.downloadError='';ui.downloadProgress=0;render();const planSnapshot=copy(t.plan),assets=[...new Set(planSnapshot.stops.filter(s=>!P[s.id].isBreak).flatMap(s=>[P[s.id].image,P[s.id].story.audio].filter(Boolean)))];const created=[];let bytes=0;try{const reg=await navigator.serviceWorker.ready;await new Promise(resolve=>{if(navigator.serviceWorker.controller)return resolve();const timer=setTimeout(resolve,1200);navigator.serviceWorker.addEventListener('controllerchange',()=>{clearTimeout(timer);resolve()},{once:true})});const cache=await caches.open(CACHE);for(let i=0;i<assets.length;i++){const url=new URL(assets[i],location.href).href,existing=await cache.match(url);const response=await fetch(url,{cache:'reload'});if(!response.ok)throw Error('A package asset could not be fetched.');bytes+=(await response.clone().arrayBuffer()).byteLength;if(!existing)created.push(url);await cache.put(url,response);ui.downloadProgress=Math.round((i+1)/assets.length*100);render();if(ui.sim.downloadFail){ui.sim.downloadFail=false;throw Error('The next-download failure scenario was triggered.')}}db.packages[t.id]={tripId:t.id,revision:planSnapshot.revision,planSnapshot,assets,bytes,savedAt:new Date().toISOString(),contentRevision:D.contentRevision};persist();ui.downloadBusy=false;ui.downloadError='';render();toast('All package files saved. Ready offline.')}catch(e){try{const cache=await caches.open(CACHE);for(const url of created)await cache.delete(url)}catch(_){}ui.downloadBusy=false;ui.downloadError='Download interrupted. '+e.message+' Your saved tour and any previous complete package are unchanged.';render()}}
async function removePackage(id){const pack=db.packages[id];if(!pack)return;delete db.packages[id];persist();if('caches'in window){const cache=await caches.open(CACHE);const used=new Set(Object.values(db.packages).flatMap(p=>p.assets));for(const asset of pack.assets)if(!used.has(asset))await cache.delete(new URL(asset,location.href).href)}render();toast('Downloaded package removed; saved tour kept')}
async function askQuestion(question){const p=P[ui.placeId],q=question.trim();if(!q)return;const list=ui.askMessages[p.id]||(ui.askMessages[p.id]=[]);list.push({role:'user',text:q});const norm=s=>s.toLowerCase().replace(/[?.!]/g,'').trim();const match=p.questions.find(x=>norm(x.q)===norm(q)),key=p.id+':'+norm(q),cached=db.answers[key];if(offline()){list.push(cached?{role:'assistant',...cached,cached:true}:{role:'assistant',text:'A new answer is unavailable offline. Use this place’s downloaded transcript, or reconnect. No itinerary changes were made.'});render();return}ui.askBusy=true;render();await new Promise(r=>setTimeout(r,550));const answer=match?{text:match.a,sourceIds:match.sourceIds}:{text:'I do not have a verified answer to that question in this demo. Choose a sample question or consult the linked venue sources. I will not invent opening hours, prices or access information.',sourceIds:[]};list.push({role:'assistant',...answer});if(match){db.answers[key]=answer;persist()}ui.askBusy=false;render();document.querySelector('.scroll').scrollTop=document.querySelector('.scroll').scrollHeight}
