/* V7 discovery refresh. These adapters keep the existing guarded editor and
 * package engine while sharing one navigation, conversation and audio state. */
ui.aiContext={scope:'city'};ui.detailTab='about';ui.aiDrafts={};
const reviewerMode=new URLSearchParams(location.search).get('review')==='1';
const reviewPanelBeforeRefresh=reviewPanel;
reviewPanel=()=>reviewerMode?reviewPanelBeforeRefresh():'';
nav=()=>`<nav class="bottom-nav" aria-label="Primary">${[['home','Home','home'],['explore','Explore','compass'],['ai','AI Guide','chat'],['trips','Trips','trips']].map(([r,l,i])=>`<button data-action="nav" data-value="${r}" class="${ui.route===r?'active':''}" ${ui.route===r?'aria-current="page"':''}>${icon(i)}${l}</button>`).join('')}</nav>`;
const headerBeforeRefresh=header;
header=(title,options='')=>['explore','ai','trips'].includes(ui.route)?`<header class="topbar"><div class="title">${esc(title)}</div>${options}</header>`:headerBeforeRefresh(title,options);

welcomeView=function(){const n=ui.welcomeStep,content=[null,['HEAR THE CITY','Every place has<br>a story.','Listen at each stop, or discover a story wherever you are.'],['FIND YOUR DA NANG','Follow your<br>curiosity.','Explore the map, save a place and make room for a little discovery.'],['YOUR TIME · YOUR PACE','A day that<br>feels like you.','Choose your time and interests. Review an AI suggestion, then make it your own.']][n];return {title:'Welcome',noheader:true,body:`<div class="welcome-screen ${n===2?'welcome-second':n===3?'welcome-third':''}"><div class="welcome-toprow"><div class="welcome-brand">${brandLogo('color','brand-logo--welcome')}</div>${textBtn('Skip','welcome-skip')}</div>${GN_VISUALS.onboardArtwork(n)}<div class="welcome-content"><p class="eyebrow">${content[0]}</p><h1>${content[1]}</h1><p>${content[2]}</p><div class="welcome-dots" aria-label="Step ${n} of 3">${[1,2,3].map(i=>`<span class="${n===i?'active':''}"></span>`).join('')}</div><div class="welcome-actions">${n>1?`<button class="button icon-btn welcome-back-btn" data-action="welcome-back" aria-label="Back">${icon('back')}</button>`:''}${btn(n===3?'Start exploring':'Next','welcome-next',{},'welcome-next-btn','arrow')}</div></div></div>`}};
function discoveryCard(p){return `<button class="discovery-card" data-action="place" data-id="${p.id}"><img src="${p.image}" alt="${esc(p.name)}" loading="lazy"><span class="body"><strong>${esc(p.name)}</strong><small>${esc(p.category)}</small><span class="meta">${icon('headphones')}English story · ${C.formatDuration(p.duration)} visit</span></span></button>`}
homeView=function(){const t=activeTrip(),current=t&&P[t.plan.stops[t.progress.index].id];return {title:'GoNarra',noheader:true,nav:true,body:`<div class="home-map-screen" data-snap="${ui.homeSnap}"><div class="map-surface">${GN_VISUALS.mapScene(null,{selectedId:ui.selectedMapPlace})}</div><div class="home-top">${brandRow()}<div class="home-city-row"><span class="city-chip">${icon('pin')}Da Nang, Vietnam</span><span class="demo-chip">Illustrated map · no live GPS</span></div><button class="search-box home-search" data-action="home-search">${icon('search')}<span>Find places and stories</span>${icon('arrow')}</button></div><div class="home-map-tools"><button class="icon-btn map-control" data-action="map-overview" aria-label="Show map overview">${icon('compass')}</button></div><section class="home-drawer" data-snap="${ui.homeSnap}" aria-label="Discover Da Nang">${drawerGrip()}<div class="drawer-content">${t?`<div class="home-resume"><div class="grow"><p class="eyebrow">${t.status==='paused'?'TRIP PAUSED':'YOUR JOURNEY'}</p><h3>${esc(current.name)}</h3><p class="small muted">Stop ${t.progress.index+1} of ${t.plan.stops.length}</p></div>${btn(t.status==='paused'?'Resume':'Continue','open-trip',{id:t.id},'small','arrow')}</div>`:`<div class="home-quickplan"><h2>How much time is yours?</h2><div class="time-chips">${[120,240,360].map(v=>`<button data-action="quick-plan" data-value="${v}">${v/60} hours</button>`).join('')}</div></div>`}<div class="home-medium-content">${ui.selectedMapPlace?selectedMapCard(ui.selectedMapPlace):''}<div class="section-head"><h3>A story worth a stop</h3>${textBtn('Explore all','all-places')}</div><div class="discover-grid">${[P.cathedral,P.beach].map(discoveryCard).join('')}</div></div><div class="home-full-content"><div class="section-head"><h3>A day, already imagined</h3>${textBtn('All tours','explore-tours')}</div><div class="tour-strip">${D.templates.map(miniTourCard).join('')}</div><p class="fine-print">Choose a place by name or photo. Location is optional; this prototype uses manual arrival.</p></div></div></section></div>`}};
function normalized(text){return String(text).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/đ/g,'d')}
exploreView=function(){const q=normalized(ui.search),tab=ui.exploreTab||'places';let list=Object.values(P).filter(p=>!p.isBreak&&normalized(`${p.name} ${p.localName} ${p.tags.join(' ')}`).includes(q));if(ui.filter!=='all')list=list.filter(p=>p.tags.includes(ui.filter));const tours=D.templates.filter(t=>normalized(t.title+' '+t.description).includes(q));return {title:'Explore',nav:true,body:`<div class="page">${pageHero('Find your next discovery.','A place, a story, or a day by the sea.')}${searchForm(ui.search)}<div class="segmented" role="tablist" aria-label="Explore collection">${['places','tours'].map(v=>`<button role="tab" aria-selected="${v===tab}" class="${v===tab?'active':''}" data-action="explore-tab" data-value="${v}">${v==='places'?'Places & stories':'Ready-made tours'}</button>`).join('')}</div>${tab==='places'?`<div class="chip-set">${['all','culture','nature','beach'].map(v=>`<button class="chip ${ui.filter===v?'active':''}" data-action="filter" data-value="${v}" aria-pressed="${ui.filter===v}">${v==='all'?'All':v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div>${list.length?`<div class="discover-grid">${list.map(discoveryCard).join('')}</div>`:notice('No matching places. Try another name or clear the category filter.')}`:tours.length?tours.map(tourCard).join(''):notice('No matching prepared tours. Try another search.')}</div>`}};

function planShape(plan){const p=copy(plan);delete p.id;delete p.title;delete p.revision;return JSON.stringify(p)}
function matchingTemplateTrip(plan,includeActive=false){if(!plan.templateId)return null;return db.trips.find(t=>t.plan.templateId===plan.templateId&&t.plan.date===plan.date&&t.plan.revision===0&&planShape(t.plan)===planShape(plan)&&((t.status==='upcoming'&&t.progress.index===0&&!t.progress.visited.length&&!t.progress.skipped.length)||(includeActive&&t.status==='active')))}
function personalTrip(plan){const id='trip-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),t={id,plan:{...copy(plan),id,title:`${plan.title} · ${plan.date}`,revision:plan.revision||0},status:'upcoming',progress:{index:0,phase:'leg',visited:[],skipped:[]},createdAt:new Date().toISOString()};db.trips.unshift(t);persist();return t}
function startTour(plan,options={}){if(!plan)return;const issues=C.validate(plan);if(issues.length){toast(issues.join(' '));return}const candidate=options.tripId?db.trips.find(t=>t.id===options.tripId):matchingTemplateTrip(plan,true);if(candidate?.status==='active'){ui.tripId=candidate.id;returnTrip();return}const other=db.trips.find(t=>t.status==='active'&&t.id!==candidate?.id);if(other&&!options.confirmed){showModal('startSwitch',{plan:copy(plan),candidateId:candidate?.id||null,otherId:other.id,otherStamp:progressStamp(other)});return}if(options.confirmed&&options.otherId){const old=db.trips.find(t=>t.id===options.otherId);if(!old||old.status!=='active'||options.otherStamp!==progressStamp(old)){ui.modal=null;toast('The active journey changed. Start again to review it.');render();return}}const t=candidate||personalTrip(plan);ui.tripId=t.id;ui.proposal=null;audio.pause();beginTrip(options.confirmed===true)}
function templateDownloadState(id){const ts=db.trips.filter(t=>t.plan.templateId===id);return ts.find(t=>db.packages[t.id]?.revision===t.plan.revision)||ts.find(t=>db.packages[t.id])||ts[0]}
function miniTourCard(t){return `<div class="mini-tour-card-wrapper"><button class="mini-tour-card" data-action="tour" data-id="${t.id}"><img src="${t.image}" alt="${esc(t.title)}"><span><strong>${esc(t.title)}</strong><small>${t.stops.length} stops · ${C.formatDuration(timing(templatePlan(t.id)).totalMinutes)}</small></span></button>${downloadRow(templateDownloadState(t.id),t.id)}</div>`}
function downloadRow(t,templateId){const state=t?packageState(t):{label:'Not downloaded',type:'neutral'},ready=t&&state.label==='Ready offline';return `<div class="download-row"><span class="download-status ${ready?'ready':''}">${icon(ready?'check':'download')}${esc(ui.downloadBusy?'Downloading '+ui.downloadProgress+'%':state.label)}</span>${textBtn(ui.downloadBusy?'Downloading…':ready?'Manage':'Download',ready?'open-download':templateId?'download-template':'download-one',{id:ready?t.id:templateId||t.id},'download')}</div>`}
tourCard=function(t){const plan=templatePlan(t.id);return `<div class="tour-card-wrapper"><button class="tour-card" data-action="tour" data-id="${t.id}"><img class="cover" src="${t.image}" alt="${esc(t.title)}" loading="lazy"><span class="body"><h2>${esc(t.title)}</h2><span class="muted small">${esc(t.subtitle)}</span><span class="small">${plan.stops.length} stops · ${C.formatDuration(timing(plan).totalMinutes)} · Free</span></span></button>${downloadRow(templateDownloadState(t.id),t.id)}</div>`};
tourView=function(){const t=D.templates.find(t=>t.id===ui.templateId)||D.templates[0],plan=templatePlan(t.id);return {title:'Ready-made tour',body:`<img class="cover-bleed" src="${t.image}" alt="${esc(t.title)}"><div class="page">${badge('Free · English stories','blue')}${pageHero(t.title,t.description)}${summary(plan)}${downloadRow(templateDownloadState(t.id),t.id)}${map(plan)}<div class="section-head"><h2>Your stops</h2>${textBtn('Customize','adapt',{id:t.id},'edit')}</div>${timeline(plan,null,true)}</div>`,foot:footer(btn('Start tour','start-template',{id:t.id},'','arrow'),textBtn('Save for later','save-template',{id:t.id}),'<p class="fine-print">Weak signal along the way? Download stories above. You can start without downloading.</p>')}};
proposalView=function(){const p=ui.proposal?.plan;if(!p)return planView();return {title:'Your suggested day',body:`<div class="page">${badge('Proposal · not saved','blue')}${pageHero('Your day, thoughtfully arranged.',`${p.stops.length} stops · ${modeName(p.mode)}`)}${summary(p)}<details class="card"><summary>Why these places?</summary><p>${esc((ui.proposal.explanations||[]).join(' ')||'Matched catalogue tags and checked the time budget with local demo rules.')}</p><p class="fine-print">Travel estimates are illustrative; current venue hours are unverified.</p></details>${map(p)}<div class="section-head"><h2>Your stops</h2>${textBtn('Customize','edit-proposal',{},'edit')}</div>${timeline(p,null,true)}${textBtn('Ask for an adjustment','adjust-proposal',{},'chat')}</div>`,foot:footer(btn('Start this day','start-proposal',{},'','arrow'),textBtn('Save for later','save-proposal'))}};
readyView=function(){const t=trip();if(!t)return tripsView();return {title:'Saved tour',body:`<div class="page">${pageHero(t.plan.title,`${t.plan.date} · ${t.plan.stops.length} stops`)}${summary(t.plan)}${downloadRow(t)}<div class="two">${btn('Edit itinerary','edit-trip',{},'secondary','edit')}${btn('Ask AI','ask-trip',{},'secondary','chat')}</div>${map(t.plan)}${timeline(t.plan,null,true)}${textBtn('Transport: '+modeName(t.plan.mode),'transport',{},'car')}${textBtn('Delete saved tour…','delete-trip',{},'trash')}</div>`,foot:footer(btn('Start tour','start-trip',{},'','arrow'))}};

function detailBody(p,atStop=false){const story=ui.detailTab==='story',t=atStop?trip():null;return `<div class="place-detail-screen"><div class="detail-hero"><img src="${p.image}" alt="${esc(p.name)}"><div class="detail-hero-controls"><button class="icon-btn" data-action="back" aria-label="Back">${icon('back')}</button><button class="icon-btn ${db.favorites.includes(p.id)?'active':''}" data-action="favorite" data-id="${p.id}" aria-label="Save favorite" aria-pressed="${db.favorites.includes(p.id)}">${icon('bookmark')}</button></div></div><div class="detail-title"><p class="eyebrow">${atStop?`STOP ${t.progress.index+1} OF ${t.plan.stops.length} · ARRIVAL CONFIRMED`:esc(p.category)}</p><h1 tabindex="-1">${esc(p.name)}</h1><p>${esc(p.localName)}</p></div><div class="detail-facts"><span>${icon('clock')}${C.formatDuration(p.duration)} suggested</span>${!p.isBreak?`<span>${icon('headphones')}English story</span>`:''}</div>${!p.isBreak?`<div class="detail-tabs" role="tablist" aria-label="Place information">${['about','story'].map(v=>`<button role="tab" aria-selected="${ui.detailTab===v}" class="${ui.detailTab===v?'active':''}" data-action="detail-tab" data-value="${v}">${v==='about'?'About':'Story'}</button>`).join('')}</div>`:''}<div class="detail-copy">${story&&!p.isBreak?`${player(p)}<details ${ui.showTranscript?'open':''}><summary>Read the transcript</summary>${transcript(p)}</details>`:`<p>${esc(p.description)}</p>${!p.isBreak?btn('Listen to this story','listen-detail',{id:p.id},'','headphones'):''}<details><summary>Practical information & sources</summary>${notice('Opening hours, entrance access and fees are unverified. Check with the venue.','warning')}${p.id==='mountain'?notice('A visit may involve steps. No accessible route has been verified.','warning'):''}${sources(p)}</details>`}${!p.isBreak?`<button class="detail-ask-link" data-action="ask-place" data-id="${p.id}">${icon('chat')}Ask about this place${icon('arrow')}</button>`:''}${atStop?textBtn('Stay longer · +15 min','extend-stop',{},'clock'):''}${currentStopLink(p.id)}</div></div>`}
function currentStopLink(id){const t=activeTrip(),stop=t?.plan.stops[t.progress.index];return stop&&stop.id!==id?textBtn('Back to current stop','return-current',{},'route'):''}
function globalPlayer(){if(!audioPlace||!P[audioPlace]||!audioPlaying||ui.route==='welcome')return '';const visible=ui.route==='arrival'?trip()?.plan.stops[trip().progress.index]?.id:['place','story'].includes(ui.route)?ui.placeId:null;if(visible===audioPlace&&ui.detailTab==='story'||ui.route==='leg'&&trip()?.plan.stops[trip().progress.index]?.id===audioPlace)return '';const p=P[audioPlace],duration=Number.isFinite(audio.duration)?audio.duration:0,progress=duration?Math.min(100,(audio.currentTime||0)/duration*100):0;return `<div class="global-player"><img src="${esc(p.image)}" alt=""><button class="global-player-copy grow" data-action="story" data-id="${audioPlace}" aria-label="Open ${esc(p.name)} story"><small>NOW PLAYING · STORY</small><strong>${esc(p.name)}</strong><span class="global-player-track"><i id="global-audio-progress" style="width:${progress}%"></i></span><span id="global-audio-time">${duration?`${audioTime(audio.currentTime)} · ${audioTime(duration)}`:'Playing'}</span></button><button class="icon-btn" data-action="play" data-id="${audioPlace}" aria-label="Pause playing story">${icon('pause')}</button></div>`}
placeView=()=>({title:'Place details',noheader:true,body:detailBody(P[ui.placeId]),foot:footer(btn('Add to trip','add-place-target',{id:ui.placeId},'secondary','plus'))});
storyView=()=>({title:'Story',noheader:true,body:detailBody(P[ui.placeId]),foot:''});
arrivalView=function(){const t=trip();if(!t)return tripsView();const p=P[t.plan.stops[t.progress.index].id];return {title:'At your stop',noheader:true,body:detailBody(p,true),foot:footer(btn(t.progress.index===t.plan.stops.length-1?'Finish this tour':'Finish stop & continue','finish-stop',{},'','arrow'))}};
const legBeforeRefresh=legView;
legView=function(){const v=legBeforeRefresh();if(ui.route==='leg'&&trip()?.status==='active')v.body=v.body.replace(textBtn('Itinerary','itinerary',{},'calendar'),textBtn('Ask AI','ask-current',{},'chat'));return v};

let audioResume=null,audioRequest=0;
function rememberAudio(){if(audioPlace&&Number.isFinite(audio.currentTime)){db.audioPositions=db.audioPositions||{};db.audioPositions[audioPlace]=audio.currentTime}}
function restoreAudio(){if(audioResume!==null&&Number.isFinite(audio.duration)&&audio.duration>0){audio.currentTime=Math.min(audioResume,Math.max(0,audio.duration-.1));audioResume=null}}
play=async function(id){const p=P[id];if(!p)return;const token=++audioRequest;if(audioPlace===id&&!audio.paused){audio.pause();return}if(audioPlace!==id){rememberAudio();audio.pause();persist();audioPlace=id;audioError='';audioResume=db.audioPositions?.[id]||0;audio.src=p.story.audio||'';audio.currentTime=0}if(!p.story.audio){audioError='No recording is bundled for this stop.';audioLoading=false;render();return}if(offline()){const has=Object.values(db.packages).some(pk=>pk.assets.includes(p.story.audio));if(!has){audioError='This story has not been downloaded. Reconnect or read the transcript.';render();return}try{const cache=await caches.open(CACHE);if(!(await cache.match(new URL(p.story.audio,location.href).href)))throw Error('missing')}catch(e){if(token!==audioRequest)return;audioError='The cached file is unavailable. Reconnect and download again.';render();return}}if(token!==audioRequest)return;restoreAudio();audioError='';audioLoading=true;render();try{await audio.play()}catch(e){if(token!==audioRequest)return;audioLoading=false;audioError='Playback could not start. Tap Play again or read the transcript.';render()}};
window.addEventListener('pagehide',()=>{rememberAudio();persist()});

function contextTrip(ctx){return ctx.tripId?db.trips.find(t=>t.id===ctx.tripId):ctx.scope==='trip'?activeTrip():null}
function aiKey(ctx){return ctx.scope==='poi'?'poi:'+ctx.id:ctx.scope==='trip'?'trip:'+(contextTrip(ctx)?.id||'none'):'city'}
function aiMessages(ctx){db.aiConversations=db.aiConversations||{};return db.aiConversations[aiKey(ctx)]||[]}
function openAI(context={scope:'city'}){const ctx={...context};if(ctx.scope==='poi'&&!P[ctx.id])return;if(ctx.scope==='trip'){const t=contextTrip(ctx);if(!t){toast('Start or save a trip first, or plan a new day.');ctx.scope='city'}else ctx.tripId=t.id}ui.aiContext=ctx;if(ctx.sheet)showModal('aiSheet',{context:copy(ctx)});else go('ai')}
function aiBody(ctx,sheet=false){const p=ctx.scope==='poi'?P[ctx.id]:null,t=contextTrip(ctx),messages=aiMessages(ctx),label=p?p.name:t?t.plan.title:'Da Nang',suggestions=p?p.questions.map(q=>q.q):t?['More beach time','Less walking','Only culture','Make it 3 hours']:['What can I do in Da Nang?','How do audio stories work?'];return `<div class="ai-page"><div class="ai-contextbar"><span class="ai-context-chip active">${icon(p?'pin':t?'trips':'compass')}${esc(label)}</span>${!sheet?`${ctx.scope==='city'?'':'<button class="ai-context-chip" data-action="ai-context" data-value="city">Da Nang</button>'}${activeTrip()?`<button class="ai-context-chip" data-action="ai-context" data-value="trip">Current trip</button>`:''}`:textBtn('Open full AI Guide','ai-expand',{},'external')}</div>${!messages.length?`<div class="ai-welcome"><span class="ai-mark">${icon('chat')}</span><div><p class="eyebrow">AI GUIDE · LOCAL DEMO</p><h1>${p?'Ask about this place.':t?'Adjust what comes next.':'What would make today feel right?'}</h1><p>${p?'Answers use the listed place sources.':t?'Current and completed visits stay fixed. You review every change.':'Ask by text or try the voice interaction. Start with time, pace or what interests you.'}</p></div></div>`:''}${!p&&!t?`<div class="ai-suggestions"><strong>Plan by available time</strong><div class="time-chips">${[120,240,360].map(v=>`<button data-action="quick-plan" data-value="${v}">${v/60} hours</button>`).join('')}</div></div>`:''}<div class="ai-suggestions">${suggestions.map(q=>`<button data-action="ai-prompt" data-value="${esc(q)}">${esc(q)}${icon('arrow')}</button>`).join('')}</div>${t&&ctx.scope==='trip'?`<div class="ai-contextbar"><span class="fine-print">Protected: ${esc([...new Set([...preserved(t),...t.plan.stops.filter(s=>s.locked).map(s=>s.id)])].map(id=>P[id].name).join(', ')||'No fixed visits yet')}. Current and past visits keep their position and duration.</span></div>`:''}<div class="ai-conversation" aria-live="polite">${messages.map(m=>`<div class="bubble ${m.role==='user'?'user':''}"><h3>${m.role==='user'?'You':m.cached?'Saved answer':'GoNarra · demo'}</h3><p>${esc(m.text)}</p>${m.sourceIds&&p?sources(p,m.sourceIds):''}${m.placeId?textBtn('View place','place',{id:m.placeId}):''}</div>`).join('')}${ui.aiDrafts[aiKey(ctx)]?`<div class="ai-response-card">${badge('Suggestion · not applied','blue')}<h3>Changes for the rest of your day</h3><p>${esc(ui.aiDrafts[aiKey(ctx)].changes.join(' '))}</p>${btn('Review changes','ai-review',{},'secondary','route')}</div>`:''}</div><div class="ai-composer"><form data-form="ai"><div class="search-box"><input name="q" aria-label="Ask AI Guide" placeholder="Ask about your journey…" maxlength="400" required><button class="voice-trigger" type="button" data-action="voice-open" aria-label="Try voice input">${icon('mic')}</button><button class="icon-btn" type="submit" aria-label="Send question">${icon('arrow')}</button></div></form><p class="fine-print">Local demo · voice input, AI answers, routes and live venue checks are simulated.</p></div></div>`}
function aiReply(text,overrideCtx=null){const ctx=overrideCtx||((ui.modal?.kind==='aiSheet'?ui.modal.context:null)||ui.aiContext),key=aiKey(ctx),p=ctx.scope==='poi'?P[ctx.id]:null,t=contextTrip(ctx);db.aiConversations=db.aiConversations||{};const messages=db.aiConversations[key]||(db.aiConversations[key]=[]);messages.push({role:'user',text});let answer={role:'assistant',text:''};delete ui.aiDrafts[key];if(p){const q=p.questions.find(q=>normalized(q.q)===normalized(text)),cacheKey=p.id+'|'+text.toLowerCase().trim();if(q&&(!offline()||db.answers[cacheKey])){answer.text=q.a;answer.sourceIds=q.sourceIds;answer.cached=offline();if(!offline())db.answers[cacheKey]=copy(q)}else answer.text=offline()?'This answer is not saved offline. Read the transcript or reconnect.':'This demo answers the sample questions above. Current hours, fees and live conditions are not connected.'}else if(t){if(offline())answer.text='A new AI adjustment is unavailable offline. Your saved itinerary is unchanged.';else{const input=copy(t.plan),result=C.adjust(input,{intent:text,lockedIds:input.stops.filter(s=>s.locked).map(s=>s.id),preserveIds:preserved(t)});if(!result.ok)answer.text=result.reason;else{const changes=planChanges(t.plan,result.plan);answer.text=changes.length?'I have a suggestion for the upcoming visits. Your itinerary stays unchanged until you review and apply it.':'Your itinerary already matches this request. There are no changes to apply.';if(changes.length)ui.aiDrafts[key]={before:copy(t.plan),plan:copy(result.plan),changes,context:t.id,request:text,basePlanStamp:planStamp(t.plan),baseProgressStamp:progressStamp(t)}}}}else if(/audio|stor|listen|nghe/.test(normalized(text)))answer.text='Open a place and tap Listen. Story audio works independently of your trip. Download a tour before a weak-signal journey; arrival stays manual in this demo.';else if(/da nang|what can|discover|kham pha/.test(normalized(text))){answer.text='Start with Da Nang Cathedral for architecture, the Museum of Cham Sculpture for culture, or My Khe Beach for a coastal pause. Choose your available time above to review a suggested day.';answer.placeId='cathedral'}else answer.text='I can introduce the demo places, explain audio stories, or help plan a day using the time chips. Live weather, bookings and unrestricted AI answers are not connected.';messages.push(answer);if(messages.length>40)messages.splice(0,messages.length-40);persist();ui.keepScroll=true;render()}
function quickPlanView(){const r=req();return `<form data-form="quick-plan" class="stack"><div class="section-head"><h2>Plan my day</h2><button class="icon-btn" type="button" data-action="close-modal" aria-label="Close">${icon('close')}</button></div><p class="small muted">A few choices, then a suggestion to review.</p><div class="two"><label>Date<input name="date" type="date" required value="${esc(r.date)}"></label><label>Start time<input name="time" type="time" required value="${C.formatTime(r.startMinutes)}"></label></div><div class="two"><label>Time available<select name="budget">${[120,240,360].map(v=>`<option value="${v}" ${v===r.budget?'selected':''}>${v/60} hours</option>`).join('')}</select></label><label>Travel<select name="mode"><option value="car" ${r.mode==='car'?'selected':''}>Car / taxi passenger</option><option value="walking" ${r.mode==='walking'?'selected':''}>Walking</option></select></label></div><label>Start point<select name="startId">${['river','cathedral','museum','beach'].map(id=>`<option value="${id}" ${r.startId===id?'selected':''}>${esc(startName(id))}</option>`).join('')}</select></label><fieldset><legend>Interests · choose at least one</legend><div class="two">${[['culture','Culture'],['nature','Nature'],['history','History'],['beach','Beach']].map(([v,l])=>`<label class="choice"><input name="interests" type="checkbox" value="${v}" ${r.interests.includes(v)?'checked':''}>${l}</label>`).join('')}</div></fieldset><label>Pace<select name="pace">${['relaxed','balanced','active'].map(v=>`<option value="${v}" ${r.pace===v?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></label><p class="fine-print">${r.endMode==='start'?'Returns to the start':'Ends at the final stop'} · ${r.mustVisit.length} must-visit${r.mustVisit.length===1?'':'s'} retained · demo travel estimates.</p>${ui.error?notice(ui.error,'warning'):''}<button class="button" type="submit">${icon('route')}Create my suggested day</button>${textBtn('More options & must-visits','advanced-plan')}</form>`}
function voiceSample(ctx){const p=ctx?.scope==='poi'?P[ctx.id]:null;if(p?.questions?.length)return p.questions[0].q;if(ctx?.scope==='trip')return 'Less walking for the rest of my trip.';return 'I have four hours and prefer culture with less walking.'}
function voiceModalView(){const v=ui.voice||{},stage=v.stage||'intro',sample=voiceSample(v.context||ui.aiContext);if(stage==='listening')return `<div class="voice-sheet-head"><span class="badge blue">VOICE INPUT · DEMO</span><button class="icon-btn" data-action="voice-cancel" aria-label="Cancel voice input">${icon('close')}</button></div><div class="voice-listening" role="status"><div class="voice-orb">${icon('mic')}<span class="voice-wave"><i></i><i></i><i></i><i></i><i></i></span></div><h2>Listening to a sample…</h2><p>No microphone is recording. This state demonstrates the voice experience.</p></div>${btn('Show sample transcript','voice-review',{},'','arrow')}${textBtn('Cancel','voice-cancel')}`;if(stage==='review')return `<div class="voice-sheet-head"><div><span class="badge blue">REVIEW BEFORE SENDING</span><h2>Did we get that right?</h2></div><button class="icon-btn" data-action="voice-cancel" aria-label="Cancel voice input">${icon('close')}</button></div><label class="voice-transcript-label">Sample transcript<textarea id="voice-transcript" maxlength="400" rows="3">${esc(v.transcript||sample)}</textarea></label><p class="fine-print">Edit the words before sending. Nothing changes in a trip until you review and apply a proposal.</p>${btn('Send to AI Guide','voice-send',{},'','arrow')}${textBtn('Try sample again','voice-retry',{},'refresh')}`;return `<div class="voice-sheet-head"><div><span class="badge blue">VOICE INPUT · DEMO</span><h2>Ask without typing.</h2></div><button class="icon-btn" data-action="voice-cancel" aria-label="Close voice input">${icon('close')}</button></div><div class="voice-intro-visual"><span>${icon('mic')}</span><div class="voice-bars"><i></i><i></i><i></i><i></i><i></i></div></div><p>In the product, one tap starts a short voice request. You can review the transcript before sending it to your Guide.</p>${notice('This browser prototype does not access or record your microphone. It uses a sample transcript to demonstrate the full flow.')}<div class="voice-sample"><small>TRY SAYING</small><strong>“${esc(sample)}”</strong></div>${btn('Try sample voice','voice-start',{},'','mic')}${textBtn('Keep typing instead','voice-cancel')}`}
const modalBeforeRefresh=modalView;
modalView=function(){const m=ui.modal;if(!m)return '';let body='',cls='';if(m.kind==='aiSheet'){cls='ai-sheet';body=`<div class="section-head"><h2>AI Guide</h2><button class="icon-btn" data-action="close-modal" aria-label="Close AI Guide">${icon('close')}</button></div>${aiBody(m.context,true)}`}else if(m.kind==='voice'){cls='voice-sheet';body=voiceModalView()}else if(m.kind==='quickPlan')body=quickPlanView();else if(m.kind==='startSwitch')body=`<h2>Pause your current journey?</h2><p>Your current trip and progress stay saved. Start this tour with a separate itinerary.</p>${btn('Pause current & start','confirm-start',{},'','arrow')}${btn('Keep current trip','close-modal',{},'secondary')}`;else if(m.kind==='settings'&&!reviewerMode)body=`<div class="section-head"><h2>Settings</h2><button class="icon-btn" data-action="close-modal" aria-label="Close settings">${icon('close')}</button></div>${btn('Replay welcome','welcome-replay',{},'secondary','compass')}${btn('Manage downloads','downloads',{},'secondary','download')}${btn('Audio language · English','language',{},'outline','headphones')}<details><summary>About this prototype</summary><p>GoNarra V7. Audio, saved trips and browser downloads work. AI planning, GPS, maneuvers and venue changes are demonstrations.</p><a href="../Product-Handbook.html" target="_blank" rel="noopener">Read the product handbook</a></details>${textBtn('Reset local demo data…','reset',{},'trash')}`;else return modalBeforeRefresh();return `<div class="modal-backdrop" data-action="backdrop"><section class="modal ${cls}" role="dialog" aria-modal="true" aria-label="${esc(m.kind)}">${body}</section></div>`};

Object.assign(views,{welcome:welcomeView,home:homeView,explore:exploreView,place:placeView,story:storyView,arrival:arrivalView,tour:tourView,proposal:proposalView,ready:readyView,leg:legView,ai:()=>({title:'AI Guide',body:aiBody(ui.aiContext),nav:true})});
const startConfirmedBeforeRefresh=actions['confirm-start'];
function closeVoice(resume=true){const v=ui.voice||{},returnModal=v.returnModal||null,shouldResume=resume&&v.resumeAudio&&audioPlace;ui.modal=returnModal;ui.voice={stage:'intro',transcript:'',context:null,resumeAudio:false,returnModal:null};ui.keepScroll=true;render();if(shouldResume)play(audioPlace)}
Object.assign(actions,{
 'close-modal':()=>{const m=ui.modal;if(m?.kind==='voice'){closeVoice(true);return}ui.modal=null;ui.keepScroll=true;render();if(m?.kind==='aiSheet')document.querySelector(`[data-action="${ui.route==='leg'?'ask-current':'ask-place'}"]`)?.focus({preventScroll:true})},
 backdrop:(d,e)=>{if(!e.target.classList.contains('modal-backdrop'))return;if(ui.modal?.kind==='voice'){closeVoice(true);return}ui.modal=null;render()},
 'language-transcript':()=>{const t=trip();ui.placeId=t?.plan.stops.find(s=>!P[s.id].isBreak)?.id||'cathedral';ui.detailTab='story';ui.showTranscript=true;go('story')},
 'welcome-next':()=>{if(ui.welcomeStep<3){ui.welcomeStep++;render()}else actions['welcome-skip']()},
 'welcome-back':()=>{ui.welcomeStep=Math.max(1,ui.welcomeStep-1);render()},
 'home-search':()=>{ui.exploreTab='places';go('explore')},
 'quick-filter':d=>{ui.exploreTab='places';ui.filter=d.value==='all'?'all':d.value;go('explore')},
 'explore-tours':()=>{ui.exploreTab='tours';go('explore')},
 'quick-plan':d=>{ui.tripId=null;ui.edit=null;ui.review=null;ui.pending=null;db.req.budget=Number(d.value)||240;persist();showModal('quickPlan')},
 'advanced-plan':(d,e)=>{const form=e.target.closest('form');if(form){const f=new FormData(form),parts=String(f.get('time')).split(':').map(Number);db.req={...req(),date:String(f.get('date')),startMinutes:parts[0]*60+parts[1],budget:Number(f.get('budget')),mode:String(f.get('mode')),startId:String(f.get('startId')),interests:f.getAll('interests'),pace:String(f.get('pace'))};persist()}ui.tripId=null;go('requirements')},
 'start-template':d=>startTour(templatePlan(d.id)),
 'start-proposal':()=>startTour(ui.proposal?.plan),
 'save-template':d=>{const p=templatePlan(d.id),t=matchingTemplateTrip(p)||personalTrip(p);ui.tripId=t.id;go('ready');toast('Saved for later in Trips')},
 'save-proposal':()=>{if(!ui.proposal?.plan)return;const t=personalTrip(ui.proposal.plan);ui.tripId=t.id;ui.proposal=null;go('ready');toast('Saved for later in Trips')},
 'start-trip':()=>{const t=trip();if(t)startTour(t.plan,{tripId:t.id})},
 'confirm-start':()=>{if(ui.modal?.kind==='startSwitch'){const m=ui.modal;ui.modal=null;startTour(m.plan,{tripId:m.candidateId,confirmed:true,otherId:m.otherId,otherStamp:m.otherStamp})}else if(ui.modal?.kind==='switch'){ui.modal=null;startConfirmedBeforeRefresh()}},
 'download-template':async d=>{if(ui.downloadBusy)return;const p=templatePlan(d.id),t=matchingTemplateTrip(p)||personalTrip(p);ui.tripId=t.id;await download();if(ui.downloadError)toast(ui.downloadError)},
 'download-one':async d=>{if(ui.downloadBusy)return;ui.tripId=d.id;await download();if(ui.downloadError)toast(ui.downloadError)},
 'detail-tab':d=>{ui.detailTab=d.value==='story'?'story':'about';ui.keepScroll=true;render()},
 place:d=>{if(!P[d.id])return;ui.detailTab='about';ui.placeId=d.id;go('place')},
 story:d=>{if(!P[d.id])return;ui.detailTab='story';ui.placeId=d.id;go('story')},
 'listen-detail':d=>{ui.detailTab='story';ui.placeId=d.id;ui.keepScroll=true;render();return play(d.id)},
 'ask-place':d=>openAI({scope:'poi',id:d.id,sheet:true}),
 'ask-current':()=>{const t=trip()||activeTrip();if(t)openAI({scope:'poi',id:t.plan.stops[t.progress.index].id,tripId:t.id,sheet:true})},
 'ask-trip':()=>openAI({scope:'trip',tripId:trip()?.id,sheet:true}),
 'ai-open':()=>openAI({scope:'city'}),
 'ai-context':d=>openAI({scope:d.value}),
 'ai-expand':()=>{const ctx={...ui.modal.context,sheet:false};openAI(ctx)},
 'ai-prompt':d=>aiReply(d.value),
 'voice-open':()=>{const returnModal=ui.modal?.kind==='aiSheet'?copy(ui.modal):null,context=copy(returnModal?.context||ui.aiContext||{scope:'city'}),resumeAudio=audioPlaying;ui.voice={stage:'intro',transcript:voiceSample(context),context,resumeAudio,returnModal};if(resumeAudio)audio.pause();showModal('voice')},
 'voice-start':()=>{if(ui.modal?.kind!=='voice')return;ui.voice.stage='listening';ui.voice.transcript=voiceSample(ui.voice.context);render()},
 'voice-review':()=>{if(ui.modal?.kind!=='voice')return;ui.voice.stage='review';ui.voice.transcript=voiceSample(ui.voice.context);render()},
 'voice-retry':()=>{if(ui.modal?.kind!=='voice')return;ui.voice.stage='listening';render()},
 'voice-cancel':()=>{if(ui.modal?.kind==='voice')closeVoice(true)},
 'voice-send':()=>{if(ui.modal?.kind!=='voice')return;const text=String(document.getElementById('voice-transcript')?.value||ui.voice.transcript||'').trim(),context=copy(ui.voice.context||{scope:'city'}),returnModal=ui.voice.returnModal||null;if(!text){toast('Say or enter a short request first.');return}ui.modal=returnModal;ui.voice={stage:'intro',transcript:'',context:null,resumeAudio:false,returnModal:null};aiReply(text,context)},
 'ai-review':()=>{const ctx=ui.modal?.kind==='aiSheet'?ui.modal.context:ui.aiContext,draft=ui.aiDrafts[aiKey(ctx)];if(!draft)return;ui.tripId=draft.context;ui.adjustContext={...copy(draft),tripId:draft.context,source:'trip'};newReview(draft.before,draft.plan,'ai',draft.context,draft.request)},
 'return-current':()=>{audio.pause();const t=activeTrip();if(t){ui.tripId=t.id;returnTrip()}}
});
document.addEventListener('submit',e=>{const form=e.target;if(!['ai','quick-plan'].includes(form.dataset.form))return;e.preventDefault();const f=new FormData(form);if(form.dataset.form==='ai'){const text=String(f.get('q')||'').trim();if(text)aiReply(text);return}const time=String(f.get('time')).split(':').map(Number),budget=Number(f.get('budget')),interests=f.getAll('interests');if(!interests.length||!Number.isFinite(time[0])||time[0]*60+time[1]+budget>1440){ui.error='Choose an interest and a time window that ends before midnight.';render();return}db.req={...req(),date:String(f.get('date')),startMinutes:time[0]*60+time[1],budget,mode:String(f.get('mode')),startId:String(f.get('startId')),interests,pace:String(f.get('pace'))};persist();ui.modal=null;generate()});
/* Account screens are an explicit local prototype. Passwords are validated
 * for the interaction only and are never placed in storage or sent anywhere. */
paths.user='M20 21v-2a8 8 0 0 0-16 0v2M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0';
brandRow=()=>`<div class="brand-row"><div class="brand">${brandLogo('color','brand-logo--home')}</div><button aria-label="Profile and settings" class="icon-btn map-control" data-action="profile-open">${icon('user')}</button></div>`;
function accountActive(){return !!db.session?.active&&!!db.account}
function accountAvatar(){return esc((db.account?.name||'Explorer').trim()[0]?.toUpperCase()||'G')}
function settingsRow(label,sub,action,ico){return `<button class="settings-row" data-action="${action}"><span class="circle">${icon(ico)}</span><span class="grow"><strong>${esc(label)}</strong>${sub?`<small>${esc(sub)}</small>`:''}</span>${icon('chevron')}</button>`}
function profileView(){const signed=accountActive();return {title:'Your profile',body:`<div class="page profile-page"><div class="profile-intro"><div class="profile-avatar">${signed?accountAvatar():icon('user')}</div>${badge(signed?'Demo account · this browser':'Guest explorer','blue')}<h1>${signed?esc(db.account.name):'A little more you.'}</h1><p>${signed?esc(db.account.email):'Your saved places, stories and journeys, together.'}</p>${signed?textBtn('Edit profile','profile-edit',{},'edit'):btn('Sign in','login-open',{},'','arrow')}${signed?'':textBtn('Create a demo account','signup-open')}</div><div class="profile-stats"><div><strong>${db.trips.length}</strong><span>Journeys</span></div><div><strong>${db.favorites.length}</strong><span>Saved places</span></div><div><strong>${Object.keys(db.packages).length}</strong><span>Downloads</span></div></div><div class="settings-group">${settingsRow('My journeys','Saved on this device','profile-trips','trips')}${settingsRow('Saved places',`${db.favorites.length} favorites`,'profile-favorites','bookmark')}${settingsRow('Downloads','Stories for your next journey','downloads','download')}${settingsRow('Settings','Audio, motion and privacy','settings','settings')}</div>${notice('Trips stay on this browser. Demo sign-in does not sync data to a cloud account.')}${signed?textBtn('Sign out of demo','sign-out',{},'external'):textBtn('Keep exploring as a guest','guest-continue',{},'compass')}</div>`}}
function settingsView(){const s=db.settings||{speed:1,reducedMotion:false};return {title:'Settings',body:`<div class="page settings-page">${pageHero('Make yourself comfortable.','A few small choices for the journey.')}<section class="settings-group"><h2>Listening & comfort</h2><label class="settings-control"><span><strong>Playback speed</strong><small>Applied to the shared story player</small></span><select id="settings-speed" aria-label="Playback speed setting">${[.75,1,1.25,1.5].map(v=>`<option value="${v}" ${s.speed===v?'selected':''}>${v}×</option>`).join('')}</select></label><label class="settings-control"><span><strong>Reduce animation</strong><small>Also respects your device preference</small></span><input id="settings-motion" aria-label="Reduce animation" type="checkbox" ${s.reducedMotion?'checked':''}></label>${settingsRow('Story language','English synthetic previews','language','headphones')}</section><section class="settings-group"><h2>Your app</h2>${settingsRow('Manage downloads','Audio and place information','downloads','download')}${settingsRow('Replay welcome','Three short introductions','welcome-replay','compass')}${settingsRow('Data & privacy','What is saved on this device','privacy-open','lock')}${settingsRow('About GoNarra','Prototype capabilities and limitations','about-open','info')}</section>${textBtn('Reset local demo data…','reset',{},'trash')}</div>`}}
function authView(kind){const signup=kind==='signup',forgot=kind==='forgot',reset=kind==='reset-password',title=signup?'Make it your own.':forgot?'Let’s get you back.':reset?'A fresh start.':'Welcome back.',sub=signup?'A profile for your next discovery.':forgot?'Try the password recovery interaction.':reset?'Choose a password for this demo flow.':'Your next story is waiting.';return {title:signup?'Create account':forgot?'Password help':reset?'Reset password':'Sign in',body:`<div class="page auth-page"><div class="auth-brand">${brandLogo('color','brand-logo--auth')}</div>${pageHero(title,sub)}${notice(forgot||reset?'Recovery demo only. No email is sent and no account password is changed.':'Local sign-in demo. Use sample details; no password is stored, verified or sent.')}<form data-form="${kind}" class="stack">${signup?`<label>Your name<input name="name" autocomplete="off" maxlength="50" placeholder="Explorer" required></label>`:''}${!reset?`<label>Email<input name="email" type="email" autocomplete="off" maxlength="120" placeholder="explorer@example.com" value="${esc(ui.resetEmail||(!signup&&!forgot?db.account?.email:'')||'')}" required></label>`:''}${!forgot?`<label>${reset?'New password':'Password'}<input name="password" type="password" autocomplete="off" minlength="8" maxlength="100" placeholder="Use 8 or more characters" required></label>`:''}${reset?`<label>Confirm password<input name="confirm" type="password" autocomplete="off" minlength="8" maxlength="100" required></label>`:''}${signup?`<label class="choice"><input name="terms" type="checkbox" required><span>I understand this is a local demo profile.</span></label>`:''}${ui.error?notice(ui.error,'error'):''}<button class="button" type="submit">${signup?'Create demo account':forgot?'Continue recovery demo':reset?'Finish reset demo':'Sign in to demo'}${icon('arrow')}</button></form>${!signup&&!forgot&&!reset?textBtn('Forgot password?','forgot-open'):''}${!forgot&&!reset?textBtn(signup?'Already have a demo profile? Sign in':'New here? Create a demo account',signup?'login-open':'signup-open'):''}${textBtn('Continue as a guest','guest-continue',{},'compass')}</div>`}}
function editProfileView(){if(!accountActive())return profileView();return {title:'Edit profile',body:`<div class="page auth-page"><div class="profile-avatar">${accountAvatar()}</div>${pageHero('Your name, your journey.','This profile is stored only in this browser.')}<form data-form="profile" class="stack"><label>Name<input name="name" value="${esc(db.account.name)}" maxlength="50" required></label><label>Email<input value="${esc(db.account.email)}" type="email" readonly aria-label="Demo account email"></label>${ui.error?notice(ui.error,'error'):''}<button class="button" type="submit">${icon('check')}Save profile</button></form></div>`}}
function privacyView(){return {title:'Data & privacy',body:`<div class="page">${pageHero('Your journey stays here.','How this prototype handles your data.')}<div class="card"><h2>Saved in this browser</h2><p>Trips, progress, favorite places, demo conversations, playback positions, preferences and your demo profile use local browser storage. Downloaded audio and images use the browser cache.</p><p>Signing out keeps these saved journeys. Clearing browser storage or resetting the demo removes local data. There is no cloud backup or cross-device sync.</p></div><div class="card"><h2>Location & accounts</h2><p>This build does not request GPS, microphone or notification access. Arrival is manual. Account forms demonstrate the flow; passwords are never saved or transmitted and no recovery email is sent.</p><p>External Maps and source links open a separate website when you choose them.</p></div>${textBtn('Manage downloaded files','downloads',{},'download')}${textBtn('Reset local demo data…','reset',{},'trash')}</div>`}}
function aboutView(){return {title:'About GoNarra',body:`<div class="page">${pageHero('A city. A story. Your day.','GoNarra V7 · interactive prototype')}<div class="card"><h2>What you can try</h2><p>Explore Da Nang, play five English synthetic story previews, plan a day, edit an itinerary, review AI-style adjustments and save a tour for offline listening.</p></div>${notice('AI uses local demo rules. Maps, GPS maneuvers, closures and travel times are illustrative. Weather is not connected. Narration and venue information still require review.')}<a class="button secondary" href="../Product-Handbook.html" target="_blank" rel="noopener">Read the product handbook ${icon('external')}</a></div>`}}
Object.assign(views,{profile:profileView,settings:settingsView,login:()=>authView('login'),signup:()=>authView('signup'),forgot:()=>authView('forgot'),'reset-password':()=>authView('reset-password'),'profile-edit':editProfileView,privacy:privacyView,about:aboutView,favorites:()=>({title:'Saved places',body:`<div class="page">${pageHero('Keep a little curiosity.','Places you bookmarked, ready to find again.')}${db.favorites.length?`<div class="discover-grid">${db.favorites.filter(id=>P[id]).map(id=>discoveryCard(P[id])).join('')}</div>`:notice('No saved places yet. Tap the bookmark on a place to keep it here.')}</div>`})});
const accountModalBeforeRefresh=modalView;
modalView=function(){if(ui.modal?.kind!=='signOut')return accountModalBeforeRefresh();return `<div class="modal-backdrop" data-action="backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="Sign out"><h2>Sign out of this demo?</h2><p>Your saved trips, favorites and downloads stay on this device.</p>${btn('Sign out','confirm-sign-out',{},'secondary','external')}${textBtn('Stay signed in','close-modal')}</section></div>`};
Object.assign(actions,{'profile-open':()=>go('profile'),settings:()=>go('settings'),'login-open':()=>go('login'),'signup-open':()=>go('signup'),'forgot-open':()=>go('forgot'),'profile-edit':()=>go('profile-edit'),'privacy-open':()=>go('privacy'),'about-open':()=>go('about'),'profile-favorites':()=>go('favorites'),'profile-trips':()=>go('trips'),'guest-continue':()=>go('home'),'sign-out':()=>{if(accountActive())showModal('signOut')},'confirm-sign-out':()=>{if(ui.modal?.kind!=='signOut')return;db.session=null;persist();go('profile',true);toast('Signed out. Journeys stay on this device.')}});
document.addEventListener('submit',e=>{const form=e.target,kind=form.dataset.form;if(!['login','signup','forgot','reset-password','profile'].includes(kind))return;e.preventDefault();const f=new FormData(form),email=String(f.get('email')||'').trim(),password=String(f.get('password')||''),name=String(f.get('name')||'').trim();ui.error='';if(kind==='profile'){if(!accountActive())return;if(!name){ui.error='Enter your name.';render();return}db.account.name=name.slice(0,50);persist();ui.history=ui.history.filter(x=>!['profile','profile-edit'].includes(x.route));go('profile',true);toast('Demo profile saved');return}if(kind==='reset-password'){if(password.length<8||password!==String(f.get('confirm')||'')){ui.error='Use at least 8 characters and matching passwords.';render();return}go('login');toast('Reset interaction complete. No password was stored or changed.');return}if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){ui.error='Enter a valid sample email address.';render();return}if(kind==='forgot'){ui.resetEmail=email;go('reset-password');return}if(password.length<8){ui.error='Use at least 8 characters for this demo.';render();return}if(kind==='signup'&&(!name||!f.get('terms'))){ui.error='Enter your name and acknowledge the demo.';render();return}db.account={name:kind==='signup'?name.slice(0,50):db.account?.email===email?db.account.name:'Explorer',email};db.session={active:true,demo:true};persist();ui.resetEmail='';ui.history=ui.history.filter(x=>!['profile','profile-edit','login','signup','forgot','reset-password'].includes(x.route));go('profile',true);toast('Local demo profile opened. No server sign-in occurred.')});
document.addEventListener('change',e=>{db.settings=db.settings||{speed:1,reducedMotion:false};if(['settings-speed','audio-speed'].includes(e.target.id)){const speed=Number(e.target.value);if([.75,1,1.25,1.5].includes(speed)){db.settings.speed=speed;audio.playbackRate=speed;persist()}}if(e.target.id==='settings-motion'){db.settings.reducedMotion=!!e.target.checked;persist();ui.keepScroll=true;render()}});
/* A shared, structured information layer; the guarded mutation engine above
 * remains the only writer of accepted itineraries and trip progress. */
const weatherClient=GN_WEATHER.create({storage:localStorage});
let weatherAttemptAt=0;
function refreshWeatherUI(){if(ui.modal||!['home','weather'].includes(ui.route))return;ui.keepScroll=true;render()}
async function loadWeather(force=false){weatherAttemptAt=Date.now();const request=weatherClient.load({force});refreshWeatherUI();await request;refreshWeatherUI()}
function ensureWeather(){if(ui.modal||!['home','weather'].includes(ui.route)||offline()||Date.now()-weatherAttemptAt<GN_WEATHER.FRESH_MS)return;weatherAttemptAt=Date.now();Promise.resolve().then(()=>loadWeather(false))}
const experience=GN_EXPERIENCE.create({ui,D,C,P,esc,icon,btn,textBtn,badge,pageHero,footer,notice,timing,templatePlan,trip,activeTrip,modeName,startName,map,timeline,summary,downloadRow,templateDownloadState,player,transcript,currentStopLink,brandRow,drawerGrip,selectedMapCard,sources,go,render,openAI,searchForm,packageState,getDB:()=>db,getWeather:()=>weatherClient.getState()});
Object.assign(views,experience.views);
views.ai=()=>({title:'AI Guide',noheader:true,body:aiBody(ui.aiContext),nav:true});
homeView=experience.views.home;exploreView=experience.views.explore;tourView=experience.views.tour;proposalView=experience.views.proposal;tripsView=experience.views.trips;readyView=experience.views.ready;placeView=experience.views.place;arrivalView=experience.views.arrival;storyView=experience.views.story;
const aiBodyBeforeInformation=aiBody;
aiBody=function(ctx,sheet=false){let body=aiBodyBeforeInformation(ctx,sheet);if(!sheet&&ctx.scope==='city')body=body.replace('<div class="ai-conversation"',experience.aiOverview()+'<div class="ai-conversation"');return body};
const profileBeforeInformation=profileView;
views.profile=profileBeforeInformation;
const aboutBeforeInformation=aboutView;
views.about=()=>{const v=aboutBeforeInformation();v.body=v.body.replace('Weather is not connected.','City weather uses Open-Meteo model forecasts with fetch and valid times.');return v};
const privacyBeforeInformation=privacyView;
views.privacy=()=>{const v=privacyBeforeInformation();v.body=v.body.replace('External Maps and source links open a separate website when you choose them.','Weather requests use fixed Da Nang coordinates and contact Open-Meteo. Like any network request, the provider receives your connection metadata; no GPS location, account or trip data is included. A weather snapshot is stored separately for up to six hours. External Maps and source links open a separate website when you choose them.');return v};
Object.assign(actions,{
 'home-search':()=>{ui.collectionId=null;ui.filter='all';ui.exploreTab='places';go('explore')},
 'all-places':()=>{ui.collectionId=null;ui.filter='all';ui.search='';ui.exploreTab='places';go('explore')},
 'explore-tours':()=>{ui.collectionId=null;ui.search='';ui.exploreTab='tours';go('explore')},
 'home-expand':()=>{ui.homeSnap='full';render()},
 'collection-open':d=>{if(!GN_CONTENT.collections.some(c=>c.id===d.id))return;ui.collectionId=d.id;ui.search='';ui.filter='all';ui.exploreTab='places';go('explore')},
 'collection-clear':()=>{ui.collectionId=null;ui.keepScroll=true;render()},
 'explore-clear':()=>{ui.collectionId=null;ui.filter='all';ui.search='';ui.keepScroll=true;render()},
 'weather-open':()=>go('weather'),
 'weather-refresh':()=>loadWeather(true),
 'essentials-open':()=>go('essentials'),
 'ask-active-trip':()=>openAI({scope:'trip',tripId:activeTrip()?.id,sheet:true})
});
document.addEventListener('change',e=>{if(e.target.id==='explore-sort'&&['curated','short','long'].includes(e.target.value)){ui.exploreSort=e.target.value;ui.keepScroll=true;render()}});
let drawerStart=null;
document.addEventListener('pointerdown',e=>{if(e.target.closest('.drawer-grip'))drawerStart={y:e.clientY,id:e.pointerId}});
document.addEventListener('pointerup',e=>{if(!drawerStart)return;const delta=e.clientY-drawerStart.y;drawerStart=null;if(Math.abs(delta)<35)return;const levels=['compact','medium','full'],index=levels.indexOf(ui.homeSnap);ui.homeSnap=levels[Math.max(0,Math.min(2,index+(delta<0?1:-1)))];render()});
window.addEventListener('resize',()=>render());
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&ui.modal){actions['close-modal']();return}if(e.key==='Tab'&&ui.modal){const f=[...document.querySelectorAll('.modal button:not(:disabled),.modal a,.modal input,.modal select,.modal textarea')];const first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
window.addEventListener('online',()=>render());window.addEventListener('offline',()=>render());
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('sw.js').catch(()=>{});
